// Package db opens the Postgres pool and applies the embedded goose
// migrations. Queries are generated by sqlc into package sqlcgen.
package db

import (
	"context"
	"database/sql"
	"embed"
	"fmt"
	"io/fs"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"
	"github.com/pressly/goose/v3/lock"
)

//go:embed migrations/*.sql
var migrationsFS embed.FS

// Open creates a pgx pool and verifies connectivity.
func Open(ctx context.Context, url string) (*pgxpool.Pool, error) {
	cfg, err := pgxpool.ParseConfig(url)
	if err != nil {
		return nil, fmt.Errorf("db: parse url: %w", err)
	}
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, fmt.Errorf("db: create pool: %w", err)
	}
	pingCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	if err := pool.Ping(pingCtx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("db: ping: %w", err)
	}
	return pool, nil
}

// Migrate applies all pending migrations. It is safe to run repeatedly and
// from several processes at once (a Postgres session lock serializes runs).
func Migrate(ctx context.Context, pool *pgxpool.Pool) error {
	p, sqlDB, err := newProvider(pool)
	if err != nil {
		return err
	}
	_, upErr := p.Up(ctx)
	// Closed here, before river's migration runs, not deferred to the end of
	// Migrate: goose's sql.DB holds idle connections checked out of pool
	// until it's closed, and releasing them promptly (rather than holding
	// them for the rest of Migrate's duration) leaves more headroom in a
	// pool shared with other callers while migrateRiver does its own work.
	closeErr := sqlDB.Close()
	if upErr != nil {
		return fmt.Errorf("db: migrate: %w", upErr)
	}
	if closeErr != nil {
		return fmt.Errorf("db: migrate: close goose connection: %w", closeErr)
	}
	return migrateRiver(ctx, pool)
}

// Version returns the current schema version.
func Version(ctx context.Context, pool *pgxpool.Pool) (int64, error) {
	p, sqlDB, err := newProvider(pool)
	if err != nil {
		return 0, err
	}
	defer sqlDB.Close()
	return p.GetDBVersion(ctx)
}

func newProvider(pool *pgxpool.Pool) (*goose.Provider, *sql.DB, error) {
	sub, err := fs.Sub(migrationsFS, "migrations")
	if err != nil {
		return nil, nil, err
	}
	locker, err := lock.NewPostgresSessionLocker()
	if err != nil {
		return nil, nil, err
	}
	sqlDB := stdlib.OpenDBFromPool(pool)
	p, err := goose.NewProvider(goose.DialectPostgres, sqlDB, sub, goose.WithSessionLocker(locker))
	if err != nil {
		sqlDB.Close()
		return nil, nil, fmt.Errorf("db: goose provider: %w", err)
	}
	return p, sqlDB, nil
}
